import torch
import torch.nn as nn
from cutegen.ptx_runtime import PtxModule, i32, u32, i64, u64, f32, f64

PTX_SOURCE = r"""
.version 8.0
.target sm_89
.address_size 64
.visible .entry bn2d_kernel(
    .param .u64 in_ptr,
    .param .u64 out_ptr,
    .param .u64 w_ptr,
    .param .u64 b_ptr,
    .param .u64 rm_ptr,
    .param .u64 rv_ptr,
    .param .u64 nbt_ptr,
    .param .u32 training,
    .param .f32 momentum,
    .param .f32 eps,
    .param .u32 N,
    .param .u32 C,
    .param .u32 H,
    .param .u32 W
)
{
    .shared .align 4 .b8 s_sum[1024];     // 256 * 4 bytes
    .shared .align 4 .b8 s_sumsq[1024];   // 256 * 4 bytes
    .reg .pred %p0, %p1, %p2, %p3, %p4;
    .reg .b32 %r_tid, %r_bdim, %r_bid;
    .reg .b32 %rN, %rC, %rH, %rW, %rHW, %rNHW, %r_i, %r_stride, %r_tmp1, %r_tmp2, %r_n, %r_r, %r_t0, %r_t1;
    .reg .b64 %in, %out, %w, %b, %rm, %rv, %nbt;
    .reg .b64 %addr, %addr2, %off64, %off_c, %sb_sum, %sb_sumsq, %addr_rm, %addr_rv;
    .reg .f32 %f_mom, %f_eps, %f_one_minus_mom;
    .reg .f32 %f_gamma, %f_beta;
    .reg .f32 %f_x, %f_sum, %f_sumsq, %f_mean, %f_var, %f_nhw, %f_tmp, %f_use_mean, %f_use_var, %f_invstd, %f_out;
    .reg .u32 %r_training;
    .reg .b64 %nbv;
    // Load parameters
    ld.param.u64  %in,   [in_ptr];
    ld.param.u64  %out,  [out_ptr];
    ld.param.u64  %w,    [w_ptr];
    ld.param.u64  %b,    [b_ptr];
    ld.param.u64  %rm,   [rm_ptr];
    ld.param.u64  %rv,   [rv_ptr];
    ld.param.u64  %nbt,  [nbt_ptr];
    ld.param.u32  %r_training, [training];
    ld.param.f32  %f_mom, [momentum];
    ld.param.f32  %f_eps, [eps];
    ld.param.u32  %rN,    [N];
    ld.param.u32  %rC,    [C];
    ld.param.u32  %rH,    [H];
    ld.param.u32  %rW,    [W];
    // Thread/block indices
    mov.u32 %r_tid,  %tid.x;
    mov.u32 %r_bdim, %ntid.x;
    mov.u32 %r_bid,  %ctaid.x;
    // Bounds check on channel
    setp.ge.u32 %p0, %r_bid, %rC;
    @%p0 ret;
    // Precompute sizes
    mul.lo.u32 %rHW,  %rH, %rW;
    mul.lo.u32 %rNHW, %rN, %rHW;
    // Per-channel offsets and parameter loads
    mul.wide.u32 %off_c, %r_bid, 4;
    add.u64 %addr, %w, %off_c;
    ld.global.f32 %f_gamma, [%addr];
    add.u64 %addr, %b, %off_c;
    ld.global.f32 %f_beta,  [%addr];
    add.u64 %addr_rm, %rm, %off_c;
    add.u64 %addr_rv, %rv, %off_c;
    // Init accumulators
    mov.f32 %f_sum,   0.0;
    mov.f32 %f_sumsq, 0.0;
    // First pass: accumulate sum and sumsq over NHW for this channel
    mov.u32 %r_i, %r_tid;
L_LOOP_ACC:
    setp.ge.u32 %p1, %r_i, %rNHW;
    @%p1 bra L_AFTER_ACC;
    // n = i / HW; r = i % HW
    div.u32 %r_n, %r_i, %rHW;
    mul.lo.u32 %r_tmp1, %r_n, %rHW;
    sub.u32 %r_r, %r_i, %r_tmp1;
    // t0 = n*C + c
    mul.lo.u32 %r_tmp2, %r_n, %rC;
    add.u32 %r_t0, %r_tmp2, %r_bid;
    // t1 = t0 * HW + r
    mul.lo.u32 %r_tmp2, %r_t0, %rHW;
    add.u32 %r_t1, %r_tmp2, %r_r;
    // address = base + t1 * sizeof(float)
    mul.wide.u32 %off64, %r_t1, 4;
    add.u64 %addr, %in, %off64;
    ld.global.f32 %f_x, [%addr];
    // Accumulate
    add.f32 %f_sum, %f_sum, %f_x;
    mul.f32 %f_tmp, %f_x, %f_x;
    add.f32 %f_sumsq, %f_sumsq, %f_tmp;
    add.u32 %r_i, %r_i, %r_bdim;
    bra L_LOOP_ACC;
L_AFTER_ACC:
    // Store partials to shared
    mov.u64 %sb_sum,   s_sum;
    mov.u64 %sb_sumsq, s_sumsq;
    mul.wide.u32 %off64, %r_tid, 4;
    add.u64 %addr, %sb_sum, %off64;
    st.shared.f32 [%addr], %f_sum;
    add.u64 %addr2, %sb_sumsq, %off64;
    st.shared.f32 [%addr2], %f_sumsq;
    bar.sync 0;
    // Reduce within block
    shr.u32 %r_stride, %r_bdim, 1;
L_RED_LOOP:
    setp.eq.u32 %p2, %r_stride, 0;
    @%p2 bra L_RED_DONE;
    setp.lt.u32 %p3, %r_tid, %r_stride;
    @!%p3 bra L_SKIP_REDUCE;
        // Load self
        mul.wide.u32 %off64, %r_tid, 4;
        add.u64 %addr, %sb_sum, %off64;
        ld.shared.f32 %f_sum, [%addr];
        add.u64 %addr2, %sb_sumsq, %off64;
        ld.shared.f32 %f_sumsq, [%addr2];
        // Load neighbor
        add.u32 %r_tmp1, %r_tid, %r_stride;
        mul.wide.u32 %off64, %r_tmp1, 4;
        add.u64 %addr, %sb_sum, %off64;
        ld.shared.f32 %f_tmp, [%addr];
        add.f32 %f_sum, %f_sum, %f_tmp;
        add.u64 %addr, %sb_sumsq, %off64;
        ld.shared.f32 %f_tmp, [%addr];
        add.f32 %f_sumsq, %f_sumsq, %f_tmp;
        // Store back to self
        mul.wide.u32 %off64, %r_tid, 4;
        add.u64 %addr, %sb_sum, %off64;
        st.shared.f32 [%addr], %f_sum;
        add.u64 %addr2, %sb_sumsq, %off64;
        st.shared.f32 [%addr2], %f_sumsq;
L_SKIP_REDUCE:
    bar.sync 0;
    shr.u32 %r_stride, %r_stride, 1;
    bra L_RED_LOOP;
L_RED_DONE:
    // Thread 0 computes mean/var, updates running stats if training
    setp.ne.u32 %p4, %r_tid, 0;
    @%p4 bra L_AFTER_MEAN;
    // Load totals
    ld.shared.f32 %f_sum,   [%sb_sum];
    ld.shared.f32 %f_sumsq, [%sb_sumsq];
    cvt.rn.f32.u32 %f_nhw, %rNHW;
    // mean = sum / NHW
    div.rn.f32 %f_mean, %f_sum, %f_nhw;
    // var = sumsq / NHW - mean^2
    div.rn.f32 %f_var, %f_sumsq, %f_nhw;
    mul.f32 %f_tmp, %f_mean, %f_mean;
    sub.f32 %f_var, %f_var, %f_tmp;
    // Clamp var >= 0
    setp.lt.f32 %p0, %f_var, 0.0;
    @%p0 mov.f32 %f_var, 0.0;
    // Compute 1 - momentum
    mov.f32 %f_one_minus_mom, 1.0;
    sub.f32 %f_one_minus_mom, %f_one_minus_mom, %f_mom;
    // If training: update running stats, else use running stats
    setp.ne.u32 %p1, %r_training, 0;
    @!%p1 bra L_USE_RUNNING;
        // running_mean[c] = (1-mom)*rm + mom*mean
        ld.global.f32 %f_tmp, [%addr_rm];
        mul.f32 %f_tmp, %f_tmp, %f_one_minus_mom;
        mul.f32 %f_out, %f_mean, %f_mom;
        add.f32 %f_out, %f_tmp, %f_out;
        st.global.f32 [%addr_rm], %f_out;
        // running_var[c] = (1-mom)*rv + mom*var
        ld.global.f32 %f_tmp, [%addr_rv];
        mul.f32 %f_tmp, %f_tmp, %f_one_minus_mom;
        mul.f32 %f_out, %f_var, %f_mom;
        add.f32 %f_out, %f_tmp, %f_out;
        st.global.f32 [%addr_rv], %f_out;
        // Use batch stats
        mov.f32 %f_use_mean, %f_mean;
        mov.f32 %f_use_var,  %f_var;
        // Increment num_batches_tracked once (block 0)
        setp.eq.u32 %p2, %r_bid, 0;
        @!%p2 bra L_SKIP_NBT;
            ld.global.u64 %nbv, [%nbt];
            add.s64 %nbv, %nbv, 1;
            st.global.u64 [%nbt], %nbv;
L_SKIP_NBT:
        bra L_AFTER_TRAIN_CHECK;
L_USE_RUNNING:
        // Use running stats
        ld.global.f32 %f_use_mean, [%addr_rm];
        ld.global.f32 %f_use_var,  [%addr_rv];
L_AFTER_TRAIN_CHECK:
    // invstd = 1 / sqrt(var + eps)
    add.f32 %f_tmp, %f_use_var, %f_eps;
    sqrt.rn.f32 %f_tmp, %f_tmp;
    rcp.rn.f32  %f_invstd, %f_tmp;
    // Broadcast mean and invstd via shared
    st.shared.f32 [%sb_sum],   %f_use_mean;
    st.shared.f32 [%sb_sumsq], %f_invstd;
L_AFTER_MEAN:
    bar.sync 0;
    // Load broadcasted mean/invstd
    ld.shared.f32 %f_use_mean, [%sb_sum];
    ld.shared.f32 %f_invstd,   [%sb_sumsq];
    // Second pass: normalize and write output
    mov.u32 %r_i, %r_tid;
L_LOOP_OUT:
    setp.ge.u32 %p1, %r_i, %rNHW;
    @%p1 bra L_DONE;
    // n = i / HW; r = i % HW
    div.u32 %r_n, %r_i, %rHW;
    mul.lo.u32 %r_tmp1, %r_n, %rHW;
    sub.u32 %r_r, %r_i, %r_tmp1;
    // t0 = n*C + c
    mul.lo.u32 %r_tmp2, %r_n, %rC;
    add.u32 %r_t0, %r_tmp2, %r_bid;
    // t1 = t0 * HW + r
    mul.lo.u32 %r_tmp2, %r_t0, %rHW;
    add.u32 %r_t1, %r_tmp2, %r_r;
    // address = base + t1 * sizeof(float)
    mul.wide.u32 %off64, %r_t1, 4;
    add.u64 %addr, %in, %off64;
    ld.global.f32 %f_x, [%addr];
    // y = ((x - mean) * invstd) * gamma + beta
    sub.f32 %f_tmp, %f_x, %f_use_mean;
    mul.f32 %f_tmp, %f_tmp, %f_invstd;
    mul.f32 %f_tmp, %f_tmp, %f_gamma;
    add.f32 %f_out, %f_tmp, %f_beta;
    add.u64 %addr, %out, %off64;
    st.global.f32 [%addr], %f_out;
    add.u32 %r_i, %r_i, %r_bdim;
    bra L_LOOP_OUT;
L_DONE:
    ret;
}
"""

_ptx_module = None

def _get_ptx_module():
    global _ptx_module
    if _ptx_module is None:
        _ptx_module = PtxModule(PTX_SOURCE)
    return _ptx_module

def validate_generated_code():
    # Force PTX JIT assembly and entry-point lookup during compile validation.
    _get_ptx_module().function("bn2d_kernel")

class ModelNew(nn.Module):
    def __init__(self, num_features: int):
        super().__init__()
        self.num_features = num_features
        self.weight = nn.Parameter(torch.ones(num_features, dtype=torch.float32))
        self.bias = nn.Parameter(torch.zeros(num_features, dtype=torch.float32))
        self.eps = 1e-5
        self.momentum = 0.1
        self.track_running_stats = True
        self.register_buffer("running_mean", torch.zeros(num_features, dtype=torch.float32))
        self.register_buffer("running_var", torch.ones(num_features, dtype=torch.float32))
        self.register_buffer("num_batches_tracked", torch.tensor(0, dtype=torch.long))

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        N, C, H, W = x.shape
        y = torch.empty_like(x)
        module = _get_ptx_module()
        module.launch(
            "bn2d_kernel",
            grid=(C, 1, 1),
            block=(256, 1, 1),
            arguments=[
                x,
                y,
                self.weight,
                self.bias,
                self.running_mean,
                self.running_var,
                self.num_batches_tracked,
                u32(1 if self.training else 0),
                f32(float(self.momentum)),
                f32(float(self.eps)),
                u32(int(N)),
                u32(int(C)),
                u32(int(H)),
                u32(int(W)),
            ],
            shared_memory=0,
            stream=torch.cuda.current_stream(x.device),
        )
        return y

